// Auto-generated base64 data URI for logo-icon.png — embedded directly
// in the JS bundle (not a separate file request) so the loading spinner's
// icon can never go blank/missing on a poor connection, since it's
// available the instant the page's own JS has run (unlike a separate
// image request, which can stall or fail independently). Regenerate with:
//   node -e "const fs=require('fs');console.log('data:image/png;base64,'+fs.readFileSync('logo-icon.png').toString('base64'))" > logoIconData.js
// (then wrap the printed string in: export default '...';)
export default 'data:image/png;base64,';
